import "package:flutter/material.dart"; import "../models/property.dart"; import "../services/property_service.dart"; class PropertiesProvider extends ChangeNotifier { final PropertyService _propertyService = PropertyService(); List<Property> _properties = []; List<Property> _favorites = []; List<Property> _recentlyViewed = []; bool _isLoading = false; String? _error; List<Property> get properties => _properties; List<Property> get favorites => _favorites; List<Property> get recentlyViewed => _recentlyViewed; bool get isLoading => _isLoading; String? get error => _error; Future<void> loadProperties({Map<String, dynamic>? filters}) async { _isLoading = true; _error = null; notifyListeners(); try { _properties = await _propertyService.getProperties(filters: filters); _isLoading = false; notifyListeners(); } catch (e) { _error = e.toString(); _isLoading = false; notifyListeners(); } } Future<void> loadProperty(String id) async { try { final property = await _propertyService.getProperty(id); final index = _properties.indexWhere((p) => p.id == id); if (index != -1) { _properties[index] = property; } else { _properties.add(property); } notifyListeners(); } catch (e) { _error = e.toString(); notifyListeners(); } } Future<bool> createProperty(Map<String, dynamic> propertyData, List<String> imagePaths) async { try { await _propertyService.createProperty(propertyData, imagePaths); await loadProperties(); return true; } catch (e) { _error = e.toString(); notifyListeners(); return false; } } Future<bool> updateProperty(String id, Map<String, dynamic> propertyData, List<String> imagePaths) async { try { await _propertyService.updateProperty(id, propertyData, imagePaths); await loadProperties(); return true; } catch (e) { _error = e.toString(); notifyListeners(); return false; } } Future<bool> deleteProperty(String id) async { try { await _propertyService.deleteProperty(id); _properties.removeWhere((p) => p.id == id); notifyListeners(); return true; } catch (e) { _error = e.toString(); notifyListeners(); return false; } } void clearError() { _error = null; notifyListeners(); } }
